// A package written the way a transpiled or hand-written JavaScript library
// is: the key schedule lives in an unannotated `var` that one branch fills
// with a typed array and the other with a plain array, and the mixing
// functions take it as `Array.<number>` (or take no annotations at all).
// Every element read is a number, and every read runs after the store.

var ROUNDS = 4;

function fill(seed) {
  var out = [];
  for (var i = 0; i < 12; i++) out[i] = (seed * (i + 3) + i * 7) % 251;
  return out;
}

/**
 * Mixes the state in place. `p` and `s` are the caller's own storage.
 * @param {Array.<number>} p
 * @param {Array.<number>} s
 * @returns {number}
 */
function mixOnce(p, s) {
  var n, i, left = p[0], right = s[0] >>> 1;
  left ^= s[1];
  for (i = 0; i < ROUNDS; i++) {
    n = p[left & 7];
    n += s[0x8 | ((left >>> 3) & 7)];
    n ^= p[0x4 | ((left >>> 6) & 7)];
    right ^= n ^ s[i & 7];
    p[i & 7] = (p[i & 7] ^ right) & 0xff;
    s[i & 7] = (s[i & 7] + left) & 0xff;
    left = (left + right) & 0xff;
  }
  p[8] = left;
  s[8] = right;
  return left ^ right;
}

// The same loop without annotations: every parameter is an implicit
// per-call-site type, so this one binds the storage its caller stores.
function spin(p, s, times) {
  var acc = 0;
  for (var t = 0; t < times; t++) {
    acc = (acc + mixOnce(p, s)) & 0xff;
    var last = p[p.length - 1];
    p[0] = (p[0] + last) & 0xff;
    acc = (acc + s[s.length - 1]) & 0xff;
  }
  return acc;
}

export function makePool(typed) {
  var P, S;
  if (typed) {
    P = new Int32Array(fill(9));
    S = new Int32Array(fill(5));
  } else {
    P = fill(9);
    S = fill(5);
  }
  function checksum() {
    var total = 0;
    for (var i = 0; i < P.length; i++) total = (total * 31 + P[i] + S[i]) % 65521;
    return total;
  }
  function head() {
    return [P[0], S[0], P[P.length - 1], S[S.length - 1], P.length];
  }
  function rebuild() {
    var acc = spin(P, S, 3);
    P[1] = (P[1] + acc) & 0xff;
    S[1] = (S[1] + acc) & 0xff;
  }
  return { typed: typed, checksum: checksum, head: head, rebuild: rebuild };
}
